import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';

/** A question's card. Answers arrive only when the server says you may see them. */

export const REACTIONS = {
  like: '👍',
  love: '❤️',
  haha: '😂',
  fire: '🔥',
  wow: '😮'
};
export const t = (key, params = {}) => app.translator.trans(`ernestdefoe-question-of-the-day.forum.${key}`, params);

/** The sentence for an error answer from our endpoints. */
export function errorText(error) {
  const code = error?.response?.errors?.[0]?.code;
  const key = `ernestdefoe-question-of-the-day.forum.errors.${code}`;
  if (code && app.translator.trans(key) !== key) return extractText(app.translator.trans(key));
  if (error?.status === 0) return extractText(app.translator.trans('core.lib.error.network_message'));
  if (error?.status === 403) return extractText(app.translator.trans('core.lib.error.permission_denied_message'));
  if (error?.status === 404) return extractText(t('errors.not_found'));
  return extractText(t('errors.generic'));
}

/**
 * For a .catch() after call() without `quiet`: its errorHandler has already shown the member
 * the error (app.alerts), so the rejection only needs to stop here.
 */
export function alreadyShown() {
  return undefined;
}
export function call(method, path, body, quiet = false) {
  return app.request({
    method,
    // '/qotd-questions…' and '/qotd-streaks…' are the JSON:API resources; anything else is under /api/qotd.
    url: app.forum.attribute('apiUrl') + (path.startsWith('/qotd-') ? path : '/qotd' + path),
    body,
    errorHandler: error => {
      if (!quiet) app.alerts.show({
        type: 'error'
      }, errorText(error));
      throw error;
    }
  });
}
const locale = () => app.translator.getLocale() || undefined;

/** "Tuesday, November 10" for a forum-local Y-m-d (read as a calendar date, not shifted by the viewer's timezone). */
export function dayLabel(ymd, withYear = false) {
  if (!ymd) return '';
  const [y, mo, d] = ymd.split('-').map(Number);
  const options = {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC'
  };
  if (withYear) options.year = 'numeric';
  return new Intl.DateTimeFormat(locale(), options).format(new Date(Date.UTC(y, mo - 1, d)));
}
export function shortDay(ymd) {
  if (!ymd) return '';
  const [y, mo, d] = ymd.split('-').map(Number);
  return new Intl.DateTimeFormat(locale(), {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC'
  }).format(new Date(Date.UTC(y, mo - 1, d)));
}

/** "5h 12m" until a moment. */
export function until(iso) {
  const ms = Math.max(0, new Date(iso).getTime() - Date.now());
  const h = Math.floor(ms / 36e5);
  const min = Math.floor(ms % 36e5 / 6e4);
  return h ? extractText(t('time.hours_minutes', {
    hours: h,
    minutes: min
  })) : extractText(t('time.minutes', {
    minutes: Math.max(1, min)
  }));
}
export function profileUrl(person) {
  return app.route('user', {
    username: person.slug
  });
}

/** A JSON:API document from the qotd-questions / qotd-streaks resources. */

/** The document's rows, flat: id plus attributes, with `rel(row, name)` to reach what was included. */
export function rows(doc) {
  const list = Array.isArray(doc.data) ? doc.data : [doc.data];
  return list.map(r => ({
    ...r.attributes,
    id: Number(r.id),
    _r: r
  }));
}
export function rel(doc, row, name) {
  const link = row._r.relationships?.[name]?.data;
  return link && doc.included?.find(i => i.type === link.type && i.id === link.id) || null;
}

/** A `users` resource as the small Person the components draw. */
export function personOf(user) {
  if (!user) return null;
  const a = user.attributes;
  return {
    id: Number(user.id),
    name: a.displayName || a.username,
    username: a.username,
    slug: a.slug || a.username,
    avatar: a.avatarUrl || null
  };
}

/** A JSON:API body for the qotd-questions resource. */
export function doc(attributes, id) {
  return {
    data: {
      type: 'qotd-questions',
      ...(id ? {
        id: String(id)
      } : {}),
      attributes
    }
  };
}